import sys

def main():
    flags = []
    filepath = None
    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and len(arg) > 1 and not arg.lstrip('-').isdigit():
            for ch in arg[1:]:
                if ch in 'lwc':
                    flags.append(ch)
                else:
                    print(f"Unknown flag: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif filepath is None:
            filepath = arg
        else:
            print("Too many arguments", file=sys.stderr)
            sys.exit(1)
        i += 1

    if not flags:
        flags = ['l', 'w', 'c']

    # Determine input source
    if filepath is None or filepath == '-':
        import io
        data = sys.stdin.buffer.read()
        f = io.BytesIO(data)
    else:
        with open(filepath, 'rb') as fh:
            data = fh.read()
        f = io.BytesIO(data)

    line_count = 0
    word_count = 0
    char_count = len(data)

    # Count lines: a final line without trailing newline still counts
    text = data.decode('latin-1')  # safe binary-to-text roundtrip
    lines = text.split('\n')
    if text.endswith('\n'):
        line_count = len(lines) - 1
    else:
        line_count = len(lines)

    # Count words
    words = text.split()
    word_count = len(words)

    # Output in fixed order: l, w, c
    results = []
    for flag in flags:
        if flag == 'l':
            results.append(str(line_count))
        elif flag == 'w':
            results.append(str(word_count))
        elif flag == 'c':
            results.append(str(char_count))

    print(' '.join(results))

if __name__ == '__main__':
    main()

